async function dec(f){try{return await createImageBitmap(f)}catch(e){}const u=URL.createObjectURL(f);try{const im=new Image();im.decoding='async';await new Promise((ok,no)=>{im.onload=ok;im.onerror=no;im.src=u});if(!im.naturalWidth&&!/svg/i.test(f.type+f.name))throw 0;const w=im.naturalWidth||800,h=im.naturalHeight||Math.round(w*.75),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);return await createImageBitmap(c)}finally{URL.revokeObjectURL(u)}}
async function cmp(f,m=1200,kb=150){try{const bm=await dec(f);let s=Math.min(1,m/Math.max(bm.width,bm.height)),q=.85,u;for(let i=0;i<8;i++){const c=document.createElement('canvas');c.width=Math.round(bm.width*s);c.height=Math.round(bm.height*s);c.getContext('2d').drawImage(bm,0,0,c.width,c.height);u=c.toDataURL('image/webp',q);if(u.length*.75<kb*1024)break;if(q>.55)q-=.1;else s*=.85}return u}catch(e){alert('This picture could not be read ('+(f.type||f.name)+'). Please save it as JPG, PNG or WEBP and upload it again.');return ''}}

async function fit(f,W=900,H=675,kb=70){try{const bm=await dec(f);const sc=Math.min(1,1600/Math.max(bm.width,bm.height)),w=Math.max(1,Math.round(bm.width*sc)),h=Math.max(1,Math.round(bm.height*sc));const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(bm,0,0,w,h);const id=x.getImageData(0,0,w,h),a=id.data;let tr=false;for(let i=3;i<a.length;i+=4*97)if(a[i]<10){tr=true;break}
if(!tr){const L=(X,Y)=>{const i=(Y*w+X)*4;return[a[i],a[i+1],a[i+2]]},dd=(p,q)=>Math.hypot(p[0]-q[0],p[1]-q[1],p[2]-q[2]),bp=[];for(let X=0;X<w;X+=3){bp.push(L(X,0),L(X,h-1))}for(let Y=0;Y<h;Y+=3){bp.push(L(0,Y),L(w-1,Y))}const md=k=>{const v=bp.map(p=>p[k]).sort((m,n)=>m-n);return v[v.length>>1]},bg=[md(0),md(1),md(2)];if(bp.filter(p=>dd(p,bg)<80).length/bp.length>.75){const mk=new Uint8Array(w*h),st=[],CAP=100,STEP=7;const near=(k,X,Y)=>{const i=(Y*w+X)*4;return Math.hypot(a[i]-bg[0],a[i+1]-bg[1],a[i+2]-bg[2])<CAP};const tryN=(k,X,Y,j)=>{if(mk[k])return;const i=k*4,q=j*4;if(Math.hypot(a[i]-a[q],a[i+1]-a[q+1],a[i+2]-a[q+2])<STEP&&near(k,X,Y)){mk[k]=1;st.push(k)}};const seed=(X,Y)=>{const k=Y*w+X,i=k*4;if(!mk[k]&&Math.hypot(a[i]-bg[0],a[i+1]-bg[1],a[i+2]-bg[2])<70){mk[k]=1;st.push(k)}};for(let X=0;X<w;X++){seed(X,0);seed(X,h-1)}for(let Y=0;Y<h;Y++){seed(0,Y);seed(w-1,Y)}while(st.length){const k=st.pop(),X=k%w,Y=(k-X)/w;if(X>0)tryN(k-1,X-1,Y,k);if(X<w-1)tryN(k+1,X+1,Y,k);if(Y>0)tryN(k-w,X,Y-1,k);if(Y<h-1)tryN(k+w,X,Y+1,k)}let n=0;for(let k=0;k<mk.length;k++)n+=mk[k];if(n/mk.length>.03&&n/mk.length<.95){const ed=new Uint8Array(w*h);for(let k=0;k<mk.length;k++)if(!mk[k]){const X=k%w,Y=(k-X)/w;if((X>0&&mk[k-1])||(X<w-1&&mk[k+1])||(Y>0&&mk[k-w])||(Y<h-1&&mk[k+w]))ed[k]=1}for(let k=0;k<mk.length;k++){if(mk[k])a[k*4+3]=0;else if(ed[k])a[k*4+3]=110}x.putImageData(id,0,0)}}}
let x0=w,y0=h,x1=0,y1=0;const d2=x.getImageData(0,0,w,h).data;for(let Y=0;Y<h;Y++)for(let X=0;X<w;X++)if(d2[(Y*w+X)*4+3]>40){if(X<x0)x0=X;if(X>x1)x1=X;if(Y<y0)y0=Y;if(Y>y1)y1=Y}if(x1<=x0||y1<=y0){x0=0;y0=0;x1=w-1;y1=h-1}const bw=x1-x0+1,bh=y1-y0+1,s2=Math.min(W*.9/bw,H*.9/bh,2);const o=document.createElement('canvas');o.width=W;o.height=H;const ox=o.getContext('2d');ox.imageSmoothingQuality='high';ox.drawImage(c,x0,y0,bw,bh,(W-bw*s2)/2,(H-bh*s2)/2,bw*s2,bh*s2);let q=.92,u;for(let i=0;i<8;i++){u=o.toDataURL('image/webp',q);if(u.length*.75<kb*1024)break;q-=.07}return u}catch(e){return cmp(f)}}
